challenge.verificationSource:
mod solution;

fn main() {
    let cases = [
    (r#"[1,2,3,4]"#, r#"24"#),
    (r#"[1,2,3]"#, r#"6"#),
    (r#"
[1,2,3]
"#, r#"6"#),
    (r#"  
[1,2,3,4]
  "#, r#"24"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS permutations");
}
